<?php $rows=qall('SELECT o.*,u.name customer FROM orders o LEFT JOIN users u ON u.id=o.user_id ORDER BY o.id DESC');$editId=(int)($_GET['edit'] ?? 0);$showHidden=($_GET['view'] ?? '')==='deleted';$visibleRows=array_filter($rows,static fn($o)=>(bool)$o['tracking_hidden']===$showHidden); ?>
<?php foreach($rows as $o): if((int)$o['id']!==$editId)continue; ?>
<section class="erp-card erp-form-narrow"><div class="erp-card-head"><div><h2>Edit Tracking <?= e($o['order_code']) ?></h2><p>Menyimpan tracking akan menampilkannya kembali pada akun pelanggan.</p></div></div><form method="post" class="erp-form"><input type="hidden" name="action" value="admin_tracking_save"><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><input type="hidden" name="csrf" value="<?= e(admin_management_csrf()) ?>"><label>Kurir<input name="courier" maxlength="80" value="<?= e($o['courier']) ?>" placeholder="Contoh: JNE"></label><label>Nomor Resi<input name="tracking_number" maxlength="100" value="<?= e($o['tracking_number']) ?>"></label><button class="erp-btn">Simpan Tracking</button><a href="?page=admin&tab=tracking">Batal</a></form></section>
<?php endforeach; ?>
<section class="erp-card"><div class="erp-card-head"><div><h2><?= $showHidden?'Tracking Dihapus':'Tracking Pengiriman' ?></h2><p>Hapus tracking untuk menyembunyikannya dari pelanggan; pesanan tetap tersimpan.</p></div><a href="?page=admin&tab=tracking<?= $showHidden?'':'&view=deleted' ?>"><?= $showHidden?'Tracking Aktif':'Tracking Dihapus' ?></a></div><div class="erp-table-wrap"><table><thead><tr><th>Pesanan</th><th>Pelanggan</th><th>Kurir / Resi</th><th>Status Tracking</th><th>Aksi</th></tr></thead><tbody>
<?php if(!$visibleRows): ?><tr><td colspan="5">Belum ada tracking.</td></tr><?php endif; ?>
<?php foreach($visibleRows as $o): ?><tr><td><?= e($o['order_code']) ?></td><td><?= e($o['customer'] ?? '-') ?></td><td><?= e($o['courier'] ?: '-') ?><small><?= e($o['tracking_number'] ?: '-') ?></small></td><td><?= $o['tracking_hidden']?'Dihapus / disembunyikan':'Aktif' ?></td><td><div class="management-row-actions"><a href="?page=admin&tab=tracking&edit=<?= (int)$o['id'] ?><?= $showHidden?'&view=deleted':'' ?>"><?= $o['tracking_hidden']?'Pulihkan Tracking':'Edit Tracking' ?></a><?php if(!$o['tracking_hidden']): ?><form method="post" onsubmit="return confirm('Hapus tracking ini? Pesanan tetap tersimpan.')"><input type="hidden" name="action" value="admin_tracking_delete"><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><input type="hidden" name="csrf" value="<?= e(admin_management_csrf()) ?>"><button class="erp-link-danger">Hapus Tracking</button></form><?php endif; ?></div></td></tr><?php endforeach; ?>
</tbody></table></div></section>
